"""Reports over parsed entries."""
from decimal import Decimal


def _single_currency(entries):
    """Raise ValueError unless every entry shares one currency."""
    currencies = {entry.currency for entry in entries}
    if len(currencies) > 1:
        raise ValueError(
            "entries span multiple currencies: " + ", ".join(sorted(currencies))
        )


def _month_key(day):
    """Zero-padded 'YYYY-MM' key for a day, e.g. '2026-08'."""
    return f"{day.year:04d}-{day.month:02d}"


def monthly_totals(entries):
    """Sum amounts per calendar month.

    Returns a dict mapping "YYYY-MM" to the Decimal total, with its keys in
    chronological order. All entries must share one currency, otherwise
    ValueError is raised. An empty input returns an empty dict.
    """
    _single_currency(entries)
    totals = {}
    for entry in entries:
        key = (entry.day.year, entry.day.month)
        totals[key] = totals.get(key, Decimal("0.00")) + entry.amount
    return {
        f"{year:04d}-{month:02d}": total
        for (year, month), total in sorted(totals.items())
    }


def category_breakdown(entries, month):
    """Totals per category for one month, given as "YYYY-MM".

    Returns a list of (category, total) tuples sorted by total ascending, so
    the largest expense comes first, with ties broken by category name.
    Categories whose total is exactly zero are left out. Entries from other
    months are ignored. Same single-currency rule as monthly_totals.
    """
    _single_currency(entries)
    totals = {}
    for entry in entries:
        if _month_key(entry.day) != month:
            continue
        totals[entry.category] = (
            totals.get(entry.category, Decimal("0.00")) + entry.amount
        )
    ranked = [(category, total) for category, total in totals.items() if total != 0]
    ranked.sort(key=lambda item: (item[1], item[0]))
    return ranked

